def process_temperature(temp):
    if temp < 0:
        print("Freezing!")
    elif temp < 10:
        print("Very cold")
    elif temp < 20:
        print("Cool")
    elif temp < 30:
        print("Warm")
    else:
        print("Hot!")

def calculate_factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "Cannot divide by zero"
    except TypeError:
        return "Invalid types for division"

def analyze_command(cmd):
    match cmd.split():
        case ["quit"]:
            return "Exiting program"
        case ["help"]:
            return "Displaying help information"
        case ["save", filename]:
            return f"Saving to {filename}"
        case _:
            return "Unknown command"
